const reportedPlayoffStalls = new WeakSet();

function reportPlayoffStall(state, season) {
  if (!reportedPlayoffStalls.has(season)) {
    reportedPlayoffStalls.add(season);
    $(state, a("Playoff advancement paused because the bracket is invalid.",
      "季后赛对阵数据异常，已暂停推进。",
      "季後賽對陣資料異常，已暫停推進。"));
  }
  return false;
}

function resolvePlayoffByes(state, season) {
  while (season.phase === "playoffs") {
    const teams = season.alive;
    if (!Array.isArray(teams)) return reportPlayoffStall(state, season);
    const remaining = teams.filter(index => index !== Em);
    const mySlot = teams.indexOf(season.me);
    if (mySlot < 0 || remaining.length !== new Set(remaining).size ||
        remaining.some(index => !Number.isInteger(index) || !season.teams?.[index])) {
      return reportPlayoffStall(state, season);
    }
    if (teams.length === 1) {
      season.phase = "done";
      season.champion = season.team;
      season.alive = [];
      season.finish = a("Champion", "总冠军", "總冠軍");
      return false;
    }
    if (teams.length % 2 !== 0) return reportPlayoffStall(state, season);
    const opponent = teams[season.fixed ? mySlot ^ 1 : teams.length - 1 - mySlot];
    if (opponent !== Em) return true;
    const next = UY(state, season, teams, season.me);
    if (next.length >= teams.length) return reportPlayoffStall(state, season);
    season.alive = next;
  }
  return false;
}

function finishPlayoffs(state, season, getRating) {
  while (season.phase === "playoffs") {
    const size = season.alive?.length;
    const result = H_(state, season, getRating(), 0);
    if (season.phase !== "playoffs") break;
    if (!result || season.alive.length >= size) return reportPlayoffStall(state, season);
  }
  return season.phase === "done";
}

